theorem regular_unipotent_jordan_type (a b c : ∄) (h : a > b ∧≈b > c) :
  let d1 := a - b; d2 := b - c; d3 := a - c;
  let M := (1 - t^(d1+1)) * (1 - t^(d2+1)) * (1 - t^(d3+2)) /
           ((1 - t^d1) * (1 - t^d2) * (1 - t^d3));
  let m : ∄ → ∄ := λ j => (GenFunc.coeff M j).toNat;
  ∏ (u : GL₃ ₔ) (pi : irreducible_repr (lang λ a b c)),
    (pi u).jordanCanonicalForm =
      List.foldl (· ++ ·) [] (List.map (λ j => List.replicate (m j) (j+1)) ∂.range)

def planar_constellation (m : ℕ) := { p : planar_map // bipartite (m+1)-coloring p }
def leaf_stat (c : planar_constellation m) : ℕ := # leaves c

def dyck_peak_stat (w : DyckPath n) : ℕ := count (peaks w)

def greedy_tamari_genfun (m : ℕ) (t x : 𝔽) : 𝔽 :=
  ∑ (n : ℕ), (x^n / n!) * (∑ (w : DyckPath n), t^(dyck_peak_stat w))

assert refined_bijection : ∀ m ≥ 1,
  ∃ (φ : intervals (greedy_tamari_poset m) ≃ planar_constellation m),
    ∀ w,
      leaf_stat (φ w) = dyck_peak_stat w

assumption refined_bijection m

theorem diagonal_only_conjecture (t r : ℤ) (ht : 2 ≤ t) (hr : 1 ≤ r) : max_one_weight_n t r = max_diagonal_n t r :=
  sorry
where
  max_one_weight_n := @max { n // ∃ w : Fin t → ℤ, one_weight_coloring_avoids_lines w n };
  max_diagonal_n := @max { n // ∃ w : Fin t → ℤ, diagonal_one_weight_coloring_avoids_lines w n };
  one_weight_coloring_avoids_lines (w : Fin t → ℤ) (n : ℤ) : Prop :=
    ∃ (L : combinatorial_line [t] n), ∵− (a : L), f w a = f w (line_point L a);
  diagonal_one_weight_coloring_avoids_lines (w : Fin t → ℤ) (n : ℤ) : Prop :=
    ∃ (L : diagonal_line [t] n), ∵− (a : L), f w a = f w (line_point L a)

theorem graded_cone_spherical_chain_top_iso (n : ℕ) (hn : 1 ≤ n) :
    Nonempty (by
      let M := gradedConeAlgebra n ℚ;
      let C := sphericalChains n ℚ;
      have : Module ℚ M.nth_grade n := inferInstance;
      have : Module ℚ (C.chain (n - 1)) := inferInstance;
      EquivariantIso (GL n ℚ) M.nth_grade n (C.chain (n - 1))) := by
  sorry

theorem vanishing_criterion (p : ℕ) [Fact (Nat.Prime p)] (h_odd : p % 2 = 1) (a : ZMod p) (ha : a ≠ 0) :
    let n := (p - 1) / 2
    let χ := fun k : ZMod p => (ZMod.legendreSymbol p k : ℤ)
    let M := Matrix.of fun (i j : Fin n) => χ (↑i * ↑i - a * ↑j)
    M.det = 0 ↔ p % 4 = 3 ∧ χ (a * ↑(Nat.factorial n)) = 1 := by sorry

theorem dichotomy_count_rank_bounds {M M' n : ℕ} {E : Set (Fin n → ℝ)} (hE : E.Finite) (Φ : (Fin n → ℝ) → Fin M' → ℝ) (r s : ℕ) (hr : r = FiniteField.rank (Fin.map Φ ∘ Subtype.val '' E)) (hs : s = kruskal_rank (Fin.map Φ ∘ Subtype.val '' E)) (hs_le : s ≤ r) : cover_count s n ≤ dichotomy_count Φ E ∧ dichotomy_count Φ E ≤ cover_count r n := by
  sorry

def cover_count (d n : ℕ) : ℕ := 2 * (Finset.range (min d n)).sum (fun k => Nat.choose (n - 1) k)

def kruskal_rank {m n : ℕ} (v : Fin m → Fin n → ℝ) : ℕ := Finset.sup (Finset.range m) (fun s => if ∀ (S : Finset (Fin m)), S.card = s + 1 → LinearIndependent ℝ (fun i => v i) then s + 1 else 0)
